import React, { useState, useEffect } from "react";
import {
  Box,
  Grid,
  useBreakpointValue,
  Tab,
  TabList,
  TabPanel,
  TabPanels,
  Tabs,
  Text,
  Heading,
} from "@chakra-ui/react";
import SkillCard from "./SkillCard";
export const skillsData = [
  {
    icon: "https://upload.wikimedia.org/wikipedia/commons/6/6a/JavaScript-logo.png",
    name: "Javascript",
    category: "frontend",
  },
  {
    icon: "https://www.w3.org/html/logo/downloads/HTML5_Badge_512.png",
    name: "HTML",
    category: "frontend",
  },
  {
    icon: "https://somesh9870.github.io/static/media/CSS.9f33c557b92e4e2e1cc8.png",
    name: "CSS",
    category: "frontend",
  },
  {
    icon: "https://alih6051.github.io/static/media/tailwind.e7b4a92d5aefbddd6f0651c024144be2.svg",
    name: "Tailwind",
    category: "frontend",
  },
  {
    icon: "https://somesh9870.github.io/static/media/React.20adfb35ae6a6e5817bf.png",
    name: "React",
    category: "frontend",
  },
  {
    icon: "https://somesh9870.github.io/static/media/Redux.5de70b7bc0d2556a0958.png",
    name: "Redux",
    category: "frontend",
  },
  {
    icon: "https://alih6051.github.io/static/media/chakra.15320604467d004df871.png",
    name: "Chakra UI",
    category: "frontend",
  },
  {
    icon: "https://somesh9870.github.io/static/media/Node.js.478c590a266bed215577.png",
    name: "Node JS",
    category: "backend",
  },
  {
    icon: "https://somesh9870.github.io/static/media/Express.39a0f4c3d981885c64f8.png",
    name: "Express",
    category: "backend",
  },
  {
    icon: "https://alih6051.github.io/static/media/mongodb.6835c61a518a732eb8318d43dfe8f700.svg",
    name: "MongoDB",
    category: "backend",
  },
  {
    icon: "https://somesh9870.github.io/static/media/mongoose.998152e4bc5fdd366c2c.png",
    name: "Mongoose",
    category: "backend",
  },
  {
    icon: "data:image/png;base64,",
    name: "Git",
    category: "tool",
  },
  {
    icon: "data:image/png;base64,",
    name: "Postman",
    category: "tool",
  },
  {
    icon: "https://code.visualstudio.com/assets/images/code-stable.png",
    name: "VS code",
    category: "tool",
  },
  {
    icon: "https://rangav.gallerycdn.vsassets.io/extensions/rangav/vscode-thunder-client/2.5.1/1678365054933/Microsoft.VisualStudio.Services.Icons.Default",
    name: "Thunder",
    category: "tool",
  },
  {
    icon: "https://cdn-icons-png.flaticon.com/512/2175/2175377.png",
    name: "Github",
    category: "tool",
  }
];

const SkillsList = () => {
  const frontend_skills = skillsData.filter(
    (skill) => skill.category === "frontend"
  );

  const backend_skills = skillsData.filter(
    (skill) => skill.category === "backend"
  );
  const tools = skillsData.filter((skill) => skill.category === "tool");
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 400);
  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth <= 390);
    };

    window.addEventListener("resize", handleResize);

    return () => {
      window.removeEventListener("resize", handleResize);
    };
  }, []);
  return (
    <Box h="70%">
      <Heading fontSize={{ base: "3xl", md: "4xl", lg: "5xl" }}>
        <Text
          as={"span"}
          position={"relative"}
          _after={{
            content: "''",
            width: "full",
            height: useBreakpointValue({ base: "20%", md: "30%" }),
            position: "absolute",
            bottom: 1,
            left: 0,
            bg: "blue.400",
            zIndex: -1,
          }}
        >
          Technical Skills
        </Text>
      </Heading>
      <Tabs variant="unstyled" align="center">
        <TabList
          my={5}
          display="grid"
          gridTemplateColumns={isMobile ? "1fr 1fr" : "auto auto auto auto"}
          gridGap="10px"
        >
          <Tab
            _selected={{ color: "white", bg: "red.400" }}
            bg="blue.500"
            color="black"
            mx={3}
            rounded="md"
          >
            All
          </Tab>
          <Tab
            _selected={{ color: "white", bg: "red.400" }}
            bg="blue.500"
            color="black"
            mx={3}
            rounded="md"
          >
            Frontend
          </Tab>
          <Tab
            _selected={{ color: "white", bg: "red.400" }}
            bg="blue.500"
            color="black"
            mx={3}
            rounded="md"
          >
            Backend
          </Tab>{" "}
          <Tab
            _selected={{ color: "white", bg: "red.400" }}
            bg="blue.500"
            color="black"
            mx={3}
            rounded="md"
          >
            Tools
          </Tab>
        </TabList>
        <TabPanels>
          <TabPanel paddingBottom="100px">
            <Grid
              templateColumns={{
                base: "repeat(2, 1fr)",
                sm: "repeat(2, 1fr)",
                md: "repeat(4, 1fr)",
                lg: "repeat(6, 1fr)",
                xl: "repeat(8, 1fr)",
              }}
              gap={10}
            >
              {skillsData.map((skill, i) => (
                <SkillCard key={i} {...skill} />
              ))}
            </Grid>
          </TabPanel>
          <TabPanel paddingBottom="100px">
            <Grid
              templateColumns={{
                base: "repeat(2, 1fr)",
                sm: "repeat(2, 1fr)",
                md: "repeat(4, 1fr)",
                lg: "repeat(6, 1fr)",
                xl: "repeat(8, 1fr)",
              }}
              gap={10}
            >
              {frontend_skills.map((skill, i) => (
                <SkillCard key={i} {...skill} />
              ))}
            </Grid>
          </TabPanel>
          <TabPanel paddingBottom="100px">
            <Grid
              templateColumns={{
                base: "repeat(2, 1fr)",
                sm: "repeat(2, 1fr)",
                md: "repeat(4, 1fr)",
                lg: "repeat(6, 1fr)",
                xl: "repeat(8, 1fr)",
              }}
              gap={10}
            >
              {backend_skills.map((skill, i) => (
                <SkillCard key={i} {...skill} />
              ))}
            </Grid>
          </TabPanel>
          <TabPanel paddingBottom="100px">
            <Grid
              templateColumns={{
                base: "repeat(2, 1fr)",
                sm: "repeat(2, 1fr)",
                md: "repeat(4, 1fr)",
                lg: "repeat(6, 1fr)",
                xl: "repeat(8, 1fr)",
              }}
              gap={10}
            >
              {tools.map((skill, i) => (
                <SkillCard key={i} {...skill}  />
              ))}
            </Grid>
          </TabPanel>
        </TabPanels>
      </Tabs>
    </Box>
  );
};

export default SkillsList;
